class Block {
	constructor(pos, sze, clr) {
		this.pos = pos;
		this.sze = sze;
		this.clr = clr;
	}

	show() {
		push();
		translate(this.pos.x, this.pos.y - this.sze.y/2, this.pos.z);
		fill(this.clr);
		noStroke();
		box(this.sze.x, this.sze.y, this.sze.z);
		pop();
	}
}

