function getColorFromPalette(pal, f) {
	function isString(str) {
		return typeof str == "string";
	}
	const i = pal.length * f;
  let clr1 = pal[~~(i+0)]; if (isString(clr1)) clr1 = color(clr1);
  let clr2 = pal[~~(i+1) % pal.length]; if (isString(clr2)) clr2 = color(clr2);
  return lerpColor(clr1, clr2, fract(i));
}

