function arrCreate2D(x, y, val = 0) {
  let arr = [];
  for (let j = 0; j < y; j++) {    
    arr[j] = [];
    for (let i = 0; i < x; i++) {
      arr[j][i] = val;
    }
  }
  return arr;
}
